//mainWindow.cpp#include "mainwindow.h"#include "ui_mainwindow.h"MainWindow::MainWindow(QWidget *parent)    : QMainWindow(parent)    , ui(new Ui::MainWindow){    ui-&gt;setupUi(this);        setWindowTitle("calculator");    QIcon icon("E:\\work\\Qt_project\\calculator\\icon.ico"); //修改为你自己的路径    this-&gt;setWindowIcon(icon);    initUi();    initConnect();}MainWindow::~MainWindow(){    delete ui;}// 初始化UI界面void MainWindow::initUi(){    layout = new QGridLayout(this);    centralWidget()-&gt;setLayout(layout);    layout-&gt;setContentsMargins(0, 0, 0, 0);    lineEdit = new QLineEdit(this);    lineEdit-&gt;setSizePolicy(QSizePolicy::Expanding, QSizePolicy::Expanding);    result = new QLabel("result",this);    result-&gt;setSizePolicy(QSizePolicy::Expanding, QSizePolicy::Expanding);    btn1 = new QPushButton("1",this);    btn1-&gt;setSizePolicy(QSizePolicy::Expanding, QSizePolicy::Expanding);    btn2 = new QPushButton("2",this);    btn2-&gt;setSizePolicy(QSizePolicy::Expanding, QSizePolicy::Expanding);    btn3 = new QPushButton("3",this);    btn3-&gt;setSizePolicy(QSizePolicy::Expanding, QSizePolicy::Expanding);    btn4 = new QPushButton("4",this);    btn4-&gt;setSizePolicy(QSizePolicy::Expanding, QSizePolicy::Expanding);    btn5 = new QPushButton("5",this);    btn5-&gt;setSizePolicy(QSizePolicy::Expanding, QSizePolicy::Expanding);    btn6 = new QPushButton("6",this);    btn6-&gt;setSizePolicy(QSizePolicy::Expanding, QSizePolicy::Expanding);    btn7 = new QPushButton("7",this);    btn7-&gt;setSizePolicy(QSizePolicy::Expanding, QSizePolicy::Expanding);    btn8 = new QPushButton("8",this);    btn8-&gt;setSizePolicy(QSizePolicy::Expanding, QSizePolicy::Expanding);    btn9 = new QPushButton("9",this);    btn9-&gt;setSizePolicy(QSizePolicy::Expanding, QSizePolicy::Expanding);    btn0 = new QPushButton("0",this);    btn0-&gt;setSizePolicy(QSizePolicy::Expanding, QSizePolicy::Expanding);    btnAdd = new QPushButton("+",this);    btnAdd-&gt;setSizePolicy(QSizePolicy::Expanding, 