ked, [this](){ numberClicked(5); });    connect(btn6, &amp;QPushButton::clicked, [this](){ numberClicked(6); });    connect(btn7, &amp;QPushButton::clicked, [this](){ numberClicked(7); });    connect(btn8, &amp;QPushButton::clicked, [this](){ numberClicked(8); });    connect(btn9, &amp;QPushButton::clicked, [this](){ numberClicked(9); });    //连接小数点和负号按钮和槽函数    connect(btnDot, &amp;QPushButton::clicked, this, &amp;MainWindow::dotClicked);    connect(btnNeg, &amp;QPushButton::clicked, this, &amp;MainWindow::negClicked);    // 连接运算符按钮和运算槽函数    connect(btnAdd, &amp;QPushButton::clicked, [this](){ setOperation(1); });    connect(btnSub, &amp;QPushButton::clicked, [this](){ setOperation(2); });    connect(btnMul, &amp;QPushButton::clicked, [this](){ setOperation(3); });    connect(btnDiv, &amp;QPushButton::clicked, [this](){ setOperation(4); });    // 连接等号按钮和计算槽函数    connect(btnEqual, &amp;QPushButton::clicked, this, &amp;MainWindow::calculate);}// 设置运算类型 1加 2减 3乘 4除void MainWindow::setOperation(int op){    if(!lineEdit-&gt;text().isEmpty()){        lastNum = lineEdit-&gt;text().toDouble();    }    switch(op){        case 1:            operationType = 1;            break;        case 2:            operationType = 2;            break;        case 3:            operationType = 3;            break;        case 4:            operationType = 4;            break;    }    lineEdit-&gt;clear();}// 数字按钮点击事件void MainWindow::numberClicked(int num){    lineEdit-&gt;setText(lineEdit-&gt;text() + QString::number(num));}// 小数点按钮点击事件void MainWindow::dotClicked(){    if(!lineEdit-&gt;text().contains('.')){        lineEdit-&gt;setText(lineEdit-&gt;text() + ".");    }}// 负号按钮点击事件void MainWindow::negClicked(){    if(lineEdit-&gt;text().startsWith('-')){        lineEdit-&gt;setText(lineEdit-&gt;text().remove(0,1));    } else {        lineEdit-&gt;setText("-" + lineEdit-&gt;text());    }}// 计算按钮点击事件void MainWindow::calculate(){    double num2 = lineEdit-&gt;text().toDouble();    double num1 = lastNum;    double res = 0.0;    switch(operationType){        case 1:            res = num1 + num2;            break;        case 2:            res = num1 - num2;            break;        case 3:            res = num1 * num2;            break;        case 4:            if(num2 != 0){                res = num1 / num2;            } else {                result-&gt;setText("Error: Div by 0");                return;            }            break;        default:            result-&gt;setText("Error: No Op");            return;    }    result-&gt;setText(QString::number(res));    lastNum = res;    lineEdit-&gt;clear();}

